function getAdminApp(){
  if(admin.apps.length) return admin.app();
  const privateKey=String(process.env.FIREBASE_PRIVATE_KEY||'').replace(/\\n/g,'\n');
  if(!process.env.FIREBASE_PROJECT_ID||!process.env.FIREBASE_CLIENT_EMAIL||!privateKey) throw new Error('Missing Firebase Admin environment variables');
  return admin.initializeApp({credential:admin.credential.cert({projectId:process.env.FIREBASE_PROJECT_ID,clientEmail:process.env.FIREBASE_CLIENT_EMAIL,privateKey}),databaseURL:process.env.FIREBASE_DATABASE_URL});
}
function json(res,status,data){res.status(status).json(data)}
module.exports=async(req,res)=>{
  res.setHeader('Cache-Control','private, no-store, max-age=0');
  if(req.method!=='GET') return json(res,405,{error:'method_not_allowed'});
  try{
    getAdminApp();
    const h=String(req.headers.authorization||'');
    if(!h.startsWith('Bearer ')) return json(res,401,{error:'unauthorized'});
    const decoded=await admin.auth().verifyIdToken(h.slice(7));
    const snap=await admin.database().ref('licenses/'+decoded.uid).once('value');
    const lic=snap.val();
    const exp=lic&&lic.expiresAt?Number(lic.expiresAt):null;
    const active=!!lic && lic.active!==false && (!exp || exp>Date.now());
    if(!active) return json(res,403,{error:'premium_expired'});
    return json(res,200,{ok:true,items:premiumItems,expiresAt:exp,duration:lic.duration||null});
  }catch(e){
    console.error(e);
    return json(res,e.code==='auth/id-token-expired'||e.code==='auth/argument-error'?401:500,{error:e.message||'server_error'});
  }
};
